            "0.6 M: (1.70 − 2.00) ÷ 2.00 × 100 = <b>−15.0%</b> → lost water → <b>0.6 M is hypertonic</b>",
            "Isotonic concentration lies between 0.2 and 0.6 M, where % change = 0 (read from the graph's x-intercept) ✅",
